const timestamps = $json.timestamps;
if (!Array.isArray(timestamps) || timestamps.length === 0) {
  throw new Error('SMARD index response contains no timestamps.');
}
const latestTimestamp = Math.max(...timestamps.map(Number).filter(Number.isFinite));
if (!Number.isFinite(latestTimestamp)) {
  throw new Error('SMARD index response contains no valid numeric timestamp.');
}
return [{
  json: {
    chunk_timestamp: latestTimestamp,
    series_url: 'https://www.smard.de/app/chart_data/4169/DE-LU/4169_DE-LU_quarterhour_' + latestTimestamp + '.json'
  }
}];

let payload = $json.body ?? $json.data ?? $json;
if (typeof payload === 'string') {
  payload = JSON.parse(payload);
}
if (!Array.isArray(payload.series)) {
  throw new Error('Unexpected SMARD response: series array is missing.');
}
const validPairs = payload.series.filter((pair) =>
  Array.isArray(pair) &&
  Number.isFinite(Number(pair[0])) &&
  pair[1] !== null &&
  pair[1] !== '' &&
  Number.isFinite(Number(pair[1]))
);
if (validPairs.length === 0) {
  throw new Error('SMARD response contains no published price points.');
}
const rows = validPairs.map((pair) => ({
  delivery_start_ms: Number(pair[0]),
  price_eur_mwh: Number(pair[1])
}));
function sqlString(value) {
  if (value === null || value === undefined) return 'null';
  return "'" + String(value).replace(/'/g, "''") + "'";
}
function sqlJson(value) {
  return sqlString(JSON.stringify(value)) + '::jsonb';
}
const workflowName = 'market_prices_smard_de_lu';
const firstTimestamp = rows[0].delivery_start_ms;
const requestUrl = 'https://www.smard.de/app/chart_data/4169/DE-LU/4169_DE-LU_quarterhour_' + firstTimestamp + '.json';
const rawJson = JSON.stringify(payload);
const sql = [
  'with source_market as (',
  '  select s.id as source_id, m.id as market_id',
  '  from energy_data.data_sources s',
  '  cross join energy_data.markets m',
  "  where s.code = 'smard'",
  "    and m.country_code = 'DE'",
  "    and m.bidding_zone = 'DE-LU'",
  '), raw_payload as (',
  '  insert into energy_data.raw_api_payloads (source_id, workflow_name, request_url, request_hash, response_status, payload)',
  '  select source_id, ' + sqlString(workflowName) + ', ' + sqlString(requestUrl) + ', md5(' + sqlString(rawJson) + '), 200, ' + sqlJson(payload),
  '  from source_market',
  '  returning id',
  '), input_rows as (',
  '  select *',
  '  from jsonb_to_recordset(' + sqlJson(rows) + ') as x(delivery_start_ms bigint, price_eur_mwh numeric)',
  '), upserted as (',
  '  insert into energy_data.market_price_points (',
  '    source_id, market_id, product, delivery_start, delivery_end, price_eur_mwh, currency,',
  '    source_published_at, source_position, resolution, raw_payload_id',
  '  )',
  '  select',
  "    sm.source_id, sm.market_id, 'quarter_hour_day_ahead',",
  "    to_timestamp(i.delivery_start_ms / 1000.0), to_timestamp(i.delivery_start_ms / 1000.0) + interval '15 minutes',",
  "    i.price_eur_mwh, 'EUR', timestamp with time zone '1970-01-01 00:00:00+00',",
  "    row_number() over (order by i.delivery_start_ms), 'PT15M', rp.id",
  '  from input_rows i',
  '  cross join source_market sm',
  '  cross join raw_payload rp',
  '  on conflict (source_id, market_id, product, delivery_start, delivery_end, source_published_at) do update',
  '  set price_eur_mwh = excluded.price_eur_mwh,',
  '      source_position = excluded.source_position,',
  '      resolution = excluded.resolution,',
  '      raw_payload_id = excluded.raw_payload_id,',
  '      ingested_at = now()',
  '  returning 1',
  ')',
  'insert into energy_data.ingestion_runs (workflow_name, source_id, finished_at, status, records_read, records_written)',
  'select ' + sqlString(workflowName) + ', sm.source_id, now(), \'success\', ' + payload.series.length + ', count(*)::integer',
  'from source_market sm',
  'cross join upserted',
  'group by sm.source_id;'
].join('\n');
return [{
  json: {
    workflow_name: workflowName,
    source: 'smard',
    records_read: payload.series.length,
    records_valid: rows.length,
    payload_created_ms: payload.meta_data?.created ?? null,
    sql
  }
}];
